import pytest
from candidate import sort_even


class TestSortEven:
    def test_sort_even_single_element_odd_position(self):
        assert sort_even([1, 2, 3]) == [1, 2, 3]

    def test_sort_even_four_elements(self):
        assert sort_even([5, 6, 3, 4]) == [3, 6, 5, 4]

    def test_sort_even_already_sorted_evens(self):
        assert sort_even([1, 9, 2, 8, 3, 7]) == [1, 9, 2, 8, 3, 7]

    def test_sort_even_reverse_sorted_evens(self):
        assert sort_even([9, 1, 8, 2, 7, 3]) == [7, 1, 8, 2, 9, 3]

    def test_sort_even_five_elements(self):
        assert sort_even([9, 8, 7, 6, 5]) == [5, 8, 7, 6, 9]

    def test_sort_even_empty_list(self):
        assert sort_even([]) == []

    def test_sort_even_single_element(self):
        assert sort_even([42]) == [42]

    def test_sort_even_two_elements_evens_unsorted(self):
        assert sort_even([3, 1]) == [3, 1]

    def test_sort_even_two_elements_evens_sorted(self):
        assert sort_even([1, 3]) == [1, 3]

    def test_sort_even_negative_numbers(self):
        assert sort_even([-3, 2, -1, 4, -5, 6]) == [-5, 2, -3, 4, -1, 6]

    def test_sort_even_mixed_positive_negative(self):
        assert sort_even([10, -5, 0, 3, -8, 2]) == [-8, -5, 0, 3, 10, 2]

    def test_sort_even_all_same_values(self):
        assert sort_even([7, 7, 7, 7, 7]) == [7, 7, 7, 7, 7]

    def test_sort_even_with_zeros(self):
        assert sort_even([3, 0, 1, 0, 2]) == [1, 0, 2, 0, 3]

    def test_sort_even_float_values(self):
        assert sort_even([3.5, 1.2, 2.1, 4.4, 0.9, 5.5]) == [0.9, 1.2, 2.1, 4.4, 3.5, 5.5]

    def test_sort_even_long_odd_length_list(self):
        assert sort_even([10, 20, 5, 30, 1, 40, 7]) == [1, 20, 5, 30, 7, 40, 10]

    def test_sort_even_long_even_length_list(self):
        assert sort_even([10, 20, 5, 30, 1, 40, 7, 50]) == [1, 20, 5, 30, 7, 40, 10, 50]

    def test_sort_even_returns_new_list_not_mutating_input(self):
        original = [5, 6, 3, 4]
        result = sort_even(original)
        assert original == [5, 6, 3, 4]
        assert result == [3, 6, 5, 4]

    def test_sort_even_none_input_raises_type_error(self):
        with pytest.raises(TypeError):
            sort_even(None)

    def test_sort_even_integer_input_raises_type_error(self):
        with pytest.raises(TypeError):
            sort_even(5)

    def test_sort_even_string_input_raises_error(self):
        with pytest.raises(AttributeError):
            sort_even("hello")

    def test_sort_even_tuple_input(self):
        with pytest.raises(TypeError):
            sort_even((5, 6, 3, 4))

    def test_sort_even_large_values(self):
        assert sort_even([10**18, 1, 10**10, 2, 10**5, 3]) == [10**5, 1, 10**10, 2, 10**18, 3]

    def test_sort_even_odd_count_with_duplicates_in_evens(self):
        assert sort_even([4, 1, 4, 2, 4, 3, 4]) == [4, 1, 4, 2, 4, 3, 4]

    def test_sort_even_evens_all_larger_than_odds(self):
        assert sort_even([100, 1, 200, 2, 300, 3]) == [100, 1, 200, 2, 300, 3]

    def test_sort_even_evens_all_smaller_than_odds(self):
        assert sort_even([1, 100, 2, 200, 3, 300]) == [1, 100, 2, 200, 3, 300]
